   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="逆转核心的临界状态：逆转核心在维持能量反转状态时，其内部约束的高密度、狂暴化虚粒子流处于一种 “亚稳态平衡”。\n该平衡极度脆弱，依赖于源晶内部的空间场约束与核心结构的绝对物理完整性。\n碰撞敏感性： 任何超过 0.1G 加速度的物理碰撞，均可能引发链式坍缩。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_411.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
