   [101]={next_id=102, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="极高危险性：逆转核心在激活反转状态时，其物理不稳定性使其成为极度危险的“行走炸弹”。任何未预期的剧烈物理冲击均可能触发链式坍缩爆炸。\n不可控性：一旦约束开始失效，级联反应无法中止。爆炸发生时间极短(<2毫秒)，无有效逃生窗口。\n多重毁灭效应：爆炸威力巨大，并伴随强EMP及高浓度虚粒子流，破坏力远超常规高爆炸药。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_411.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 713.00, 341.00, 1.00, {}, {}}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
